import { ReactNode } from 'react';
/**
 * User information to display in the popover
 */
export interface AvatarInfo {
    /** User's display name */
    name?: string;
    /** User's job title or role */
    role?: string;
    /** User's company name */
    company?: string;
    /** User's email address */
    email?: string;
}
/**
 * Available avatar types
 */
export type AvatarType = 'image' | 'initials' | 'user-icon' | 'group-icon';
/**
 * Available avatar sizes
 */
export type AvatarSize = 'xsmall' | 'small' | 'medium' | 'large';
/**
 * Available avatar states
 */
export type AvatarState = 'enabled' | 'disabled' | 'pending';
/**
 * Available avatar colors
 */
export type AvatarColor = 'auto' | 'blue' | 'green' | 'yellow' | 'pink' | 'orange' | 'cyan' | 'purple' | 'red' | 'spark';
/**
 * Props for the AvatarPopover component
 */
export interface AvatarPopoverProps {
    /** User information to display */
    info?: AvatarInfo;
    /** User name for display */
    userName?: string;
    /** Generated alt text for accessibility */
    generatedAltText?: string;
    /** Avatar element to display in the popover */
    avatarElement?: ReactNode;
}
